// Trusted HTML inside a view, exported as `@yaks/html/raw` for a view that
// would not load a serializer: each door (./mod.ts, ./dom.ts) splices it in
// where the view put it, without the element React would wrap it in.

import {
  createContext,
  createElement as h,
  type ReactElement,
  type ReactNode,
  useContext,
} from 'react'

let Fragments = createContext((html: string): ReactNode =>
  h('div', { dangerouslySetInnerHTML: { __html: html } })
)

let FragmentHtml = ({ html }: { html: string }) => useContext(Fragments)(html)

/** A fragment of trusted HTML generated by the application. */
export let raw = (html: string): ReactElement<{ html: string }> =>
  h(FragmentHtml, { html })

/** The attribute of the empty `<template>` standing for a trusted fragment
 * until the door splices it in. */
export let SLOT = 'data-yaks-fragment'

/** `node` with each trusted fragment drawn as an empty template naming it by
 * its place in `fragments`. */
export let slotted = (node: ReactNode, fragments: string[]): ReactNode =>
  h(Fragments.Provider, {
    value: (html: string) =>
      h('template', { [SLOT]: fragments.push(html) - 1 }),
  }, node)
